// Generated by OrchestKit Claude Plugin
// Created: 2026-09-13

/**
 * Detect `core.bare=true` in a working checkout, by reading config files.
 *
 * On 2026-09-12 orchestkit's `.git/config` acquired `core.bare = true` three
 * times (#4070). A `git init` run by a test fixture inside a pre-push hook,
 * from a linked worktree, re-initialised the MAIN repository through the
 * GIT_DIR git exports to hooks. With that key set, git refuses to run in the
 * primary checkout ("this operation must be run in a work tree", measured on
 * git 2.54; linked worktrees still resolve), so hooks and pushes from there
 * die and nothing names the cause. Two lanes lost time before anyone read
 * the config.
 *
 * LEAF MODULE: imports only `node:fs` and `node:path`, and never spawns git.
 * A spawn can stall for seconds under fork pressure (#2948, see git-head.ts),
 * and git's own discovery is exactly what the flip breaks.
 *
 * Scope is deliberately narrow: the flip lands in the shared config, so this
 * reads that file only (not `config.worktree` or `include.path` targets).
 */

import { readFileSync, statSync } from 'node:fs';
import { basename, dirname, join, resolve } from 'node:path';

export interface CoreBareFlip {
  /** The working checkout that carries a `.git` entry. */
  checkout: string;
  /** The config file that says `core.bare = true`. */
  config: string;
}

/** The checkout git refuses to run in: the owner of `<repo>/.git/config`. */
function brokenCheckout(flip: CoreBareFlip): string {
  const gitDir = dirname(flip.config);
  // A submodule's config lives under `.git/modules/<name>`, with no primary.
  return basename(gitDir) === '.git' ? dirname(gitDir) : flip.checkout;
}

const TRUE_VALUES = new Set(['true', 'yes', 'on', '1']);

/** Last `core.bare` value in a git config file, git boolean rules. */
function readCoreBare(configText: string): boolean {
  let inCore = false;
  let bare = false;
  for (const raw of configText.split('\n')) {
    const line = raw.trim();
    if (line === '' || line.startsWith('#') || line.startsWith(';')) continue;
    const section = line.match(/^\[\s*([A-Za-z0-9.-]+)\s*("[^"]*")?\s*\]/);
    if (section) {
      // `[core "x"]` is a subsection, not core itself.
      inCore = section[1].toLowerCase() === 'core' && section[2] === undefined;
      continue;
    }
    if (!inCore) continue;
    const kv = line.match(/^([A-Za-z][A-Za-z0-9-]*)\s*(?:=\s*(.*))?$/);
    if (kv?.[1].toLowerCase() !== 'bare') continue;
    // A bare key with no `=` is boolean true in git config.
    const value = kv[2] === undefined ? 'true' : kv[2].replace(/\s*[#;].*$/, '').replace(/^"|"$/g, '');
    bare = TRUE_VALUES.has(value.trim().toLowerCase());
  }
  return bare;
}

/** Nearest ancestor of `startDir` (inclusive) holding a `.git` entry. */
function findCheckout(startDir: string): { checkout: string; dotGit: string; isFile: boolean } | null {
  let dir = resolve(startDir);
  for (;;) {
    const dotGit = join(dir, '.git');
    try {
      const st = statSync(dotGit);
      return { checkout: dir, dotGit, isFile: st.isFile() };
    } catch {
      // No `.git` here: keep walking up. This is the normal case for every
      // directory between startDir and the checkout root.
    }
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

/**
 * Return the flipped checkout, or null when the nearest checkout is healthy,
 * there is no checkout, or its config cannot be read. A genuine bare
 * repository has no `.git` entry at its root, so it is never reported.
 */
export function findCoreBareFlip(startDir: string): CoreBareFlip | null {
  const found = findCheckout(startDir);
  if (!found) return null;

  let commonDir = found.dotGit;
  try {
    if (found.isFile) {
      // Linked worktree or submodule: `.git` is a `gitdir: <path>` pointer,
      // and a worktree's gitdir names the shared repository in `commondir`.
      const pointer = readFileSync(found.dotGit, 'utf8').match(/^gitdir:\s*(.+?)\s*$/m);
      if (!pointer) return null;
      const gitDir = resolve(found.checkout, pointer[1]);
      commonDir = gitDir;
      try {
        commonDir = resolve(gitDir, readFileSync(join(gitDir, 'commondir'), 'utf8').trim());
      } catch {
        // No commondir file: a submodule gitdir is its own common dir.
      }
    }
    const config = join(commonDir, 'config');
    return readCoreBare(readFileSync(config, 'utf8')) ? { checkout: found.checkout, config } : null;
  } catch {
    // Unreadable pointer or config: nothing can be claimed either way, and a
    // SessionStart check must never fail the session over its own I/O.
    return null;
  }
}

/** One-paragraph warning with the exact repair command. */
export function coreBareFlipWarning(flip: CoreBareFlip): string {
  return (
    `core.bare=true in ${flip.config}, but ${flip.checkout} is a working checkout. ` +
    `git refuses to run in ${brokenCheckout(flip)}, so hooks and pushes from there fail. ` +
    `Fix: git config --file ${flip.config} core.bare false (#4070)`
  );
}
